style.css:
/*
  ChatGPT 2022 - Old Web Revival
  Version 2.0
*/

/* ESQUINAS CUADRADAS */
*,
*::before,
*::after {
    border-radius: 0 !important;
}

/* BOTONES */
button {
    border-radius: 0 !important;
    box-shadow: none !important;
}

/* CAJAS DE TEXTO */
textarea,
input,
[contenteditable="true"] {
    border-radius: 0 !important;
    box-shadow: none !important;
}

/* MENÚS */
[role="menu"],
[role="dialog"],
[role="listbox"],
[role="menuitem"] {
    border-radius: 0 !important;
}

/* SIDEBAR */
aside {
    border-radius: 0 !important;
}

/* PANELES */
[class*="rounded"] {
    border-radius: 0 !important;
}

/* QUITAR SOMBRAS MODERNAS */
button,
aside,
textarea,
[role="dialog"] {
    box-shadow: none !important;
}

/* BORDES CLÁSICOS */
button,
textarea,
input {
    outline-offset: 0 !important;
}

/* ANIMACIONES */
* {
    animation-duration: 0s !important;
    transition-duration: 0s !important;
}
